"""Generated files: style and reliability rules are skipped, security rules still run."""

import pytest

from lyvern.engine.analyzers.generated import is_generated
from lyvern.engine.analyzers.go import analyze_go
from lyvern.engine.analyzers.js_ts import analyze_js_ts

PRISMA = (
    "/* !!! This is code generated by Prisma. Do not edit directly. !!! */\n"
    "/* eslint-disable */\n"
    "// biome-ignore-all lint: generated file\n"
    "// @ts-nocheck \n"
    "export const x = 1;\n"
)


def rules_js(path: str, source: str) -> set[str]:
    return {f.detection_source.split(":")[1] for f in analyze_js_ts(path, source)}


def test_generated_files_are_recognised_by_folder_name_or_header() -> None:
    assert is_generated("src/generated/prisma/client.ts", "export {}")
    assert is_generated("a/__generated__/types.ts", "")
    assert is_generated("api/user.pb.go", "package api")
    assert is_generated("src/schema.generated.ts", "")
    assert is_generated("x/plain.ts", "// @generated by a tool\nexport {}")
    assert is_generated("x/plain.go", "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x")
    assert not is_generated("src/app.ts", "// @ts-nocheck\nexport {}")
    assert not is_generated("src/regenerated_report.ts", "export const generatedAt = 1;")
    # a notice far below the header does not count
    assert not is_generated("x.ts", "export {}\n" * 400 + "// generated file")


def test_a_ts_nocheck_header_in_a_generated_file_is_not_reported() -> None:
    assert "ts-suppress" not in rules_js("src/generated/prisma/client.ts", PRISMA)
    assert "ts-suppress" not in rules_js("src/lib/plain.ts", PRISMA)  # the header alone is enough
    assert rules_js("src/lib/hand_written.ts", "// @ts-nocheck\nexport const x = 1;\n") == {
        "ts-suppress"
    }


def test_security_rules_still_run_on_generated_files() -> None:
    source = "// @generated\nconst a = eval(userInput);\ntry { run(); } catch (e) {}\ndebugger;\n"
    assert rules_js("src/generated/api.js", source) == {"eval"}  # empty catch and debugger skipped
    assert rules_js("src/api.js", source.replace("// @generated\n", "")) == {
        "eval",
        "empty-catch",
        "debugger",
    }


def test_go_generated_files_skip_reliability_rules_but_keep_security_rules() -> None:
    body = (
        "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage api\n\nfunc f() {\n"
        "\tif err != nil {\n\t}\n\th := md5.New()\n\t_ = h\n}\n"
    )
    found = {f.detection_source.split(":")[1] for f in analyze_go("api/x.pb.go", body)}
    assert found == {"weak-hash"}
    plain = {
        f.detection_source.split(":")[1]
        for f in analyze_go(
            "api/x.go", body.replace("// Code generated by protoc-gen-go. DO NOT EDIT.\n", "")
        )
    }
    assert plain == {"weak-hash", "empty-error-branch"}


@pytest.mark.parametrize("path", ["a/generated/x.ts", "b/c.pb.go", "d.generated.ts"])
def test_paths_alone_mark_generated(path: str) -> None:
    assert is_generated(path, "")
